import { test, expect } from '@playwright/test';

test.describe('Payment Flow - Invalid Card Number', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/payment');
    await expect(page).toHaveTitle(/Payment/i);
  });

  test('should display error message when entering invalid card number', async ({ page }) => {
    // Fill in the card number field with an invalid number
    const cardNumberInput = page.getByLabel(/card number/i);
    await cardNumberInput.fill('1234567890123456');

    // Fill in other required fields
    const expiryInput = page.getByLabel(/expiry|expiration/i);
    await expiryInput.fill('12/25');

    const cvvInput = page.getByLabel(/cvv|cvc/i);
    await cvvInput.fill('123');

    // Submit the form
    const submitButton = page.getByRole('button', { name: /pay|submit|checkout/i });
    await submitButton.click();

    // Verify error message is displayed
    const errorMessage = page.getByText(/invalid card number|card number is invalid/i);
    await expect(errorMessage).toBeVisible();
  });

  test('should display error for card number with special characters', async ({ page }) => {
    // Fill in the card number field with special characters
    const cardNumberInput = page.getByLabel(/card number/i);
    await cardNumberInput.fill('1234-5678-9012-3456');

    // Fill in other required fields
    const expiryInput = page.getByLabel(/expiry|expiration/i);
    await expiryInput.fill('12/25');

    const cvvInput = page.getByLabel(/cvv|cvc/i);
    await cvvInput.fill('123');

    // Submit the form
    const submitButton = page.getByRole('button', { name: /pay|submit|checkout/i });
    await submitButton.click();

    // Verify error message is displayed
    const errorMessage = page.getByText(/invalid card number|card number is invalid/i);
    await expect(errorMessage).toBeVisible();
  });

  test('should display error for card number that is too short', async ({ page }) => {
    // Fill in the card number field with a number that is too short
    const cardNumberInput = page.getByLabel(/card number/i);
    await cardNumberInput.fill('123456789012');

    // Fill in other required fields
    const expiryInput = page.getByLabel(/expiry|expiration/i);
    await expiryInput.fill('12/25');

    const cvvInput = page.getByLabel(/cvv|cvc/i);
    await cvvInput.fill('123');

    // Submit the form
    const submitButton = page.getByRole('button', { name: /pay|submit|checkout/i });
    await submitButton.click();

    // Verify error message is displayed
    const errorMessage = page.getByText(/invalid card number|card number is invalid/i);
    await expect(errorMessage).toBeVisible();
  });
});
